WITH agg AS ( SELECT a.expert_id AS agent_id, CAST( date_add( 'day', 4, date_trunc('week', CAST(a."date" AS TIMESTAMP)) ) AS DATE ) AS period, LOWER(a.metric) AS metric, a.icp_client, LOWER(a.client) AS client, LOWER(a.subclient) AS subclient, a.site, SUM(a.numerator) AS numerator, SUM(a.denominator) AS denominator FROM hive.care.expert_performance_metrics a WHERE CAST(a."date" AS DATE) BETWEEN DATE '2026-07-18' AND DATE '2026-08-28' AND LOWER(a.metric) IN ( 'client transfers','resolution rate','ocr','hold time','talk time','callback_rate','cancellation rate','erp','expert 5star','nsp100','crt','enrolled','sale opportunities' ) AND LOWER(a.icp_client) IN ( 'mob-at&t','mob-verizon','pss-at&t','pss-at&t nac','pss-verizon','xbox','mcafee','small clients' ) GROUP BY 1,2,3,4,5,6,7 ) SELECT agent_id, CAST(period AS DATE) AS week_ending, 'all' as call_type, metric, icp_client, client, subclient, site, CAST(numerator AS DOUBLE) AS numerator, CAST(denominator AS DOUBLE) AS denominator, ROUND( COALESCE( CAST(numerator AS DOUBLE) / NULLIF(CAST(denominator AS DOUBLE), 0.0), 0.000 ), 3 ) AS calc FROM agg
